from typing import Tuple

def parse_version(s: str) -> Tuple[int, ...]:
    """poor man's version comparison"""
    if not s:
        return ()
    parts = re.split(r'\D+', s)
    nums = [int(p) for p in parts if p]
    return tuple(nums)

