def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == 'semver':
        # pieces is list of dicts with keys major, minor, patch, prerelease, build
        parts = []
        for piece in pieces:
            major = piece.get('major')
            minor = piece.get('minor')
            patch = piece.get('patch')
            if major is None or minor is None or patch is None:
                continue
            version = f"{major}.{minor}.{patch}"
            prerelease = piece.get('prerelease')
            if prerelease:
                version += f"-{prerelease}"
            build = piece.get('build')
            if build:
                version += f"+{build}"
            parts.append(version)
        return ', '.join(parts)
    elif style == 'full':
        # return list of dicts as string
        return str(pieces)
    elif style == 'json':
        import json
        return json.dumps(pieces)
    elif style == 'string':
        return ' '.join(str(p) for p in pieces)
    else:
        raise ValueError(f"Unsupported style: {style}")

