def list_of_file_names(settings_dirs: Union[str, Iterable[str]], spec_option: str) -> List[str]:
    """
    Create a new IniType complex type

    Parameters
    ----------
    settings_dirs : str or iterable of str
        Directory or directories to search for files.
    spec_option : str
        File pattern to match (e.g., '*.ini', 'config_*.yaml').

    Returns
    -------
    List[str]
        Sorted list of fully qualified file paths that match the pattern.
    """
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)

    matched_files: List[str] = []

    for directory in dirs:
        try:
            for entry in os.listdir(directory):
                if fnmatch.fnmatch(entry, spec_option):
                    matched_files.append(os.path.join(directory, entry))
        except (OSError, FileNotFoundError):
            continue

    return sorted(matched_files)

